begin;
select plan(50);
select has_table('app_private','accounting_connections','accounting connection exists');
select has_table('app_private','accounting_sync_runs','durable sync runs exist');
select has_table('app_private','accounting_customer_facts','immutable customer facts exist');
select has_table('app_private','accounting_invoice_facts','normalized invoice facts exist');
select has_table('app_private','accounting_payment_facts','normalized payment facts exist');
select has_table('app_private','accounting_adjustment_facts','normalized adjustment facts exist');
select has_table('app_private','accounting_customer_reconciliations','reconciliation queue exists');
select has_table('app_private','client_accounting_snapshots','client accounting projection exists');
select has_table('app_private','accounting_status_exceptions','manual exceptions exist');
select has_function('api','accounting_start_sync',array['uuid','jsonb','uuid'],'sync command exists');
select has_function('api','accounting_client_detail',array['uuid','uuid'],'controlled eligibility/read contract exists');

insert into auth.users(id,email)values('77000000-0000-4000-8000-000000000001','accounting-manager@test.invalid'),('77000000-0000-4000-8000-000000000002','accounting-driver@test.invalid'),('77000000-0000-4000-8000-000000000003','accounting-region@test.invalid');
insert into public.user_profiles(user_id,display_name)values('77000000-0000-4000-8000-000000000001','Accounting Manager'),('77000000-0000-4000-8000-000000000002','Accounting Driver'),('77000000-0000-4000-8000-000000000003','Other Region Manager');
insert into app_private.user_roles(user_id,role_id)select'77000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='director_admin' union all select'77000000-0000-4000-8000-000000000002'::uuid,role_id from app_private.roles where role_key='driver_team' union all select'77000000-0000-4000-8000-000000000003'::uuid,role_id from app_private.roles where role_key='operations_manager';
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id)values('77000000-0000-4000-8000-000000000001','global',null),('77000000-0000-4000-8000-000000000002','team','54000000-0000-0000-0000-000000000001'),('77000000-0000-4000-8000-000000000003','service_region',gen_random_uuid());
insert into app_private.client_contacts(client_id,contact_name,mobile_e164,email,is_primary)values('57000000-0000-0000-0000-000000000001','Accounting Contact','+27825550101','migration-existing@example.invalid',true),('57000000-0000-0000-0000-000000000002','Candidate Contact','+27826660101','candidate@example.invalid',true),('57000000-0000-0000-0000-000000000001','Shared Match One','+27820000000',null,false),('57000000-0000-0000-0000-000000000002','Shared Match Two','+27820000000',null,false);
insert into app_private.external_references(source_system,entity_type,internal_entity_id,external_identifier)values('zoho-books-fake','client','57000000-0000-0000-0000-000000000001','ZC-100');

create temporary table accounting_ids(sync_id uuid);
insert into accounting_ids select(api.accounting_start_sync('77000000-0000-4000-8000-000000000001','{"provider":"zoho-books-fake","environment":"local","organizationId":"local-synthetic","syncMode":"initial_full"}',gen_random_uuid())->>'syncRunId')::uuid;
select is((select lifecycle_status from app_private.accounting_sync_runs),'pending','sync starts pending');
select throws_ok($$select api.accounting_start_sync('77000000-0000-4000-8000-000000000001','{"provider":"zoho-books-fake","environment":"local","organizationId":"local-synthetic","syncMode":"manual_refresh"}',gen_random_uuid())$$,'55000','sync_running','parallel sync rejected');
select lives_ok(format($f$select api.accounting_ingest_sync(%L,%L::jsonb)$f$,(select sync_id from accounting_ids),'{"customers":[{"externalId":"ZC-100","version":"v1","modifiedAt":"2026-08-13T06:00:00Z","displayName":"Existing Client","email":"migration-existing@example.invalid","mobile":"+27825550101","archived":false,"fingerprint":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},{"externalId":"ZC-200","version":"v1","modifiedAt":"2026-08-13T06:01:00Z","displayName":"Strong Candidate","email":"candidate@example.invalid","archived":false,"fingerprint":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"},{"externalId":"ZC-300","version":"v1","modifiedAt":"2026-08-13T06:02:00Z","displayName":"Ambiguous","mobile":"+27820000000","archived":false,"fingerprint":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"}],"invoices":[{"externalId":"ZI-100","customerExternalId":"ZC-100","version":"v1","modifiedAt":"2026-08-13T06:10:00Z","invoiceNumber":"INV-SYN-100","issueDate":"2026-01-01","dueDate":"2026-02-01","totalMinor":120000,"outstandingMinor":70000,"currency":"ZAR","status":"partially_paid","fingerprint":"dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd"}],"payments":[{"externalId":"ZP-100","customerExternalId":"ZC-100","version":"v1","modifiedAt":"2026-08-13T06:20:00Z","paymentDate":"2026-06-01","amountMinor":50000,"currency":"ZAR","reference":"PAY-SYN-100","fingerprint":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}],"adjustments":[{"externalId":"ZA-100","customerExternalId":"ZC-100","version":"v1","modifiedAt":"2026-08-13T06:30:00Z","amountMinor":-10000,"currency":"ZAR","status":"active","fingerprint":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"}],"providerMetadata":{"synthetic":true},"nextCursor":"cursor-1"}'),'fake provider full sync succeeds');
select is((select lifecycle_status from app_private.accounting_sync_runs),'succeeded','sync completes');
select is((select classification from app_private.accounting_customer_reconciliations where provider_customer_id='ZC-100'),'mapped','external reference maps customer');
select is((select classification from app_private.accounting_customer_reconciliations where provider_customer_id='ZC-200'),'strong_candidate','strong candidate surfaced');
select is((select classification from app_private.accounting_customer_reconciliations where provider_customer_id='ZC-300'),'ambiguous','ambiguous customer requires review');
select is((select normalized_status from app_private.accounting_invoice_facts),'partially_paid','invoice status normalized');
select is((select amount_minor from app_private.accounting_payment_facts),50000::bigint,'payment normalized in minor units');
select is((select amount_minor from app_private.accounting_adjustment_facts),-10000::bigint,'credit adjustment preserved');
select is((select total_outstanding_minor from app_private.client_accounting_snapshots),60000::bigint,'active credit affects outstanding snapshot');
select is((select aging_bucket from app_private.client_accounting_snapshots),'90_plus','aging bucket calculated');
select is((select derived_status from app_private.client_accounting_snapshots),'seriously_overdue','serious overdue status derived');
select is((select latest_payment_date from app_private.client_accounting_snapshots),'2026-06-01'::date,'latest payment projected');
select is((api.accounting_ingest_sync((select sync_id from accounting_ids),'{}')->>'duplicate')::boolean,true,'duplicate sync ingestion is idempotent');
select is((select count(*)from app_private.accounting_invoice_facts),1::bigint,'duplicate sync does not duplicate invoice');
select lives_ok($$select api.accounting_reconcile('77000000-0000-4000-8000-000000000001','zoho-books-fake','ZC-200','link','57000000-0000-0000-0000-000000000002','confirmed strong candidate',gen_random_uuid())$$,'candidate can be explicitly linked');
select is((select classification from app_private.accounting_customer_reconciliations where provider_customer_id='ZC-200'),'mapped','mapping becomes explicit');
select lives_ok($$select api.accounting_reconcile('77000000-0000-4000-8000-000000000001','zoho-books-fake','ZC-200','link','57000000-0000-0000-0000-000000000002','repeat mapping safe',gen_random_uuid())$$,'repeat mapping is safe');
select is((select count(*)from app_private.external_references where source_system='zoho-books-fake'and external_identifier='ZC-200'),1::bigint,'repeat mapping creates one external reference');
select lives_ok($$select api.accounting_set_exception('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001','current','temporary operational exception',null,gen_random_uuid())$$,'manual exception applies');
select is((api.accounting_client_detail('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001')->>'accountStatus'),'current','exception overrides derived status');
select is((select derived_status from app_private.client_accounting_snapshots),'seriously_overdue','exception does not alter accounting facts');
select lives_ok($$select api.accounting_remove_exception('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001','exception period ended',gen_random_uuid())$$,'manual exception removed');
select is((api.accounting_client_detail('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001')->>'accountStatus'),'seriously_overdue','removal restores derived status');
update app_private.client_accounting_snapshots set stale_after=now()-interval'1 minute';
select is((api.accounting_client_detail('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001')->>'accountStatus'),'unknown','stale snapshot reports uncertainty');
select is((api.accounting_client_detail('77000000-0000-4000-8000-000000000001','57000000-0000-0000-0000-000000000001')->'eligibility'->>'recommendation'),'review_required','eligibility contract handles staleness without operational writes');
select is((select count(*)from app_private.client_services),3::bigint,'accounting work never changes services');
select is((select count(*)from app_private.route_plans),0::bigint,'accounting work never creates routes');
insert into accounting_ids select(api.accounting_start_sync('77000000-0000-4000-8000-000000000001','{"provider":"zoho-books-fake","environment":"local","organizationId":"local-synthetic","syncMode":"incremental","cursor":"cursor-1"}',gen_random_uuid())->>'syncRunId')::uuid;
select is((select sync_mode from app_private.accounting_sync_runs where sync_mode='incremental' limit 1),'incremental','incremental sync supported');
select lives_ok(format($f$select api.accounting_fail_sync(%L,'provider_unavailable','Synthetic outage',null)$f$,(select sync_id from accounting_ids order by ctid desc limit 1)),'provider outage recorded safely');
select is((select total_outstanding_minor from app_private.client_accounting_snapshots),60000::bigint,'failed sync preserves last valid snapshot');
select is((select lifecycle_status from app_private.accounting_connections),'degraded','outage degrades provider health only');
select throws_ok($$select api.accounting_client_detail('77000000-0000-4000-8000-000000000002','57000000-0000-0000-0000-000000000001')$$,'42501',null,'Driver financial access denied');
select throws_ok($$select api.accounting_client_detail('77000000-0000-4000-8000-000000000003','57000000-0000-0000-0000-000000000001')$$,'42501',null,'cross-region financial access denied');
select throws_ok('set local role authenticated;select * from app_private.accounting_invoice_facts','42501',null,'direct authenticated access denied');
select ok((select count(*)>=4 from app_private.business_audit_facts where module_key='accounting'),'human accounting actions audited');
select ok((select count(*)>=2 from app_private.outbox_events where producer_module='accounting'),'concise accounting events emitted');
select is((select count(*)from app_private.clients),2::bigint,'accounting reconciliation never creates Clients');
select * from finish();rollback;
